import copy
import json
import math
from solution import solve


def close(actual, expected):
    if isinstance(expected, bool) or expected is None:
        return actual is expected
    if isinstance(expected, (int, float)):
        return isinstance(actual, (int, float)) and not isinstance(actual, bool) and math.isfinite(actual) and math.isclose(actual, expected, abs_tol=1e-7, rel_tol=1e-9)
    if isinstance(expected, list):
        return isinstance(actual, list) and len(actual) == len(expected) and all(close(a, e) for a, e in zip(actual, expected))
    if isinstance(expected, dict):
        return isinstance(actual, dict) and actual.keys() == expected.keys() and all(close(actual[k], v) for k, v in expected.items())
    return actual == expected


CASES = json.loads("[{\"name\":\"balanced\",\"input\":{\"hot_capacity_w_per_k\":100,\"cold_capacity_w_per_k\":100,\"ua_w_per_k\":100,\"inlet_hot_c\":100,\"inlet_cold_c\":20},\"expected\":{\"effectiveness\":0.5,\"heat_w\":4000,\"outlet_hot_c\":60,\"outlet_cold_c\":60}},{\"name\":\"no_conductance\",\"input\":{\"hot_capacity_w_per_k\":100,\"cold_capacity_w_per_k\":200,\"ua_w_per_k\":0,\"inlet_hot_c\":80,\"inlet_cold_c\":10},\"expected\":{\"effectiveness\":0,\"heat_w\":0,\"outlet_hot_c\":80,\"outlet_cold_c\":10}}]")
for case in CASES:
    value = copy.deepcopy(case["input"])
    assert close(solve(value), case["expected"]), case["name"]
    assert value == case["input"], "Do not mutate the input"
