def solve(payload):
    import math
    ch, cc, ua = [payload[k] for k in ("hot_capacity_w_per_k", "cold_capacity_w_per_k", "ua_w_per_k")]
    if ch <= 0 or cc <= 0 or ua < 0:
        return {"error": "invalid_exchanger"}
    low = min(ch, cc)
    ratio = low/max(ch, cc)
    ntu = ua/low
    if ratio == 1:
        effectiveness = ntu/(1+ntu)
    else:
        one_minus_e = -math.expm1(-ntu*(1-ratio))
        effectiveness = one_minus_e/((1-ratio)+ratio*one_minus_e)
    hot, cold = payload["inlet_hot_c"], payload["inlet_cold_c"]
    heat = effectiveness*low*(hot-cold)
    return {"effectiveness": effectiveness, "heat_w": heat, "outlet_hot_c": hot-heat/ch, "outlet_cold_c": cold+heat/cc}

